sensorValue;             //value read from the sensor\n        int sensorMax = 0;\n        uint32_t start_time = millis();\n        while((millis()-start_time) < 1000)//sample for 1000ms\n        {\n            sensorValue = analogRead(ELECTRICITY_SENSOR);\n            if (sensorValue > sensorMax)\n            {\n                /*record the maximum sensor value*/\n                sensorMax = sensorValue;\n            }\n        }\n        return sensorMax;\n    }\n'})}),"\n",(0,n.jsx)(s.admonition,{type:"note",children:(0,n.jsxs)(s.p,{children:["A corrente m\xednima efetiva que pode ser detectada pelo c\xf3digo pode ser calculada usando a equa\xe7\xe3o abaixo. minimum_current=1/1024",(0,n.jsx)(s.em,{children:"5/800"}),"2000000/1.414=8.6(mA)."]})}),"\n",(0,n.jsxs)(s.ul,{children:["\n",(0,n.jsxs)(s.li,{children:[(0,n.jsx)(s.strong,{children:"Passo 2."})," Abra o monitor serial. Os resultados s\xe3o os seguintes\uFF1A"]}),"\n"]}),"\n",(0,n.jsx)(s.p,{children:(0,n.jsx)(s.img,{src:"https://files.seeedstudio.com/wiki/Grove-Electricity_Sensor/img/ardu_result.jpg",alt:""})}),"\n",(0,n.jsx)(s.h3,{id:"com-raspberry-pi",children:"Com Raspberry Pi"}),"\n",(0,n.jsx)(s.h4,{id:"hardware-1",children:"Hardware"}),"\n",(0,n.jsxs)(s.ul,{children:["\n",(0,n.jsxs)(s.li,{children:[(0,n.jsx)(s.strong,{children:"Passo 1."})," Prepare os itens abaixo:"]}),"\n"]}),"\n",(0,n.jsxs)(s.table,{children:[(0,n.jsx)(s.thead,{children:(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.th,{children:"Raspberry pi"}),(0,n.jsx)(s.th,{children:"GrovePi_Plus"}),(0,n.jsx)(s.th,{children:"Grove-Electricity_Sensor"})]})}),(0,n.jsxs)(s.tbody,{children:[(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/wiki_english/docs/images/rasp.jpg"})})}),(0,n.jsx)(s.td,{children:(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/wiki_english/docs/images/Grovepi%2B.jpg"}